// Smooth Zooming — Interaction, route: ref
// Source: smooth-zooming
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

type View = [number, number, number];

const POINTS = 2000;
const THETA = Math.PI * (3 - Math.sqrt(5));
const DELAY = 250;

// The notebook picks each destination with Math.random(); a fixed cycle of positions
// along the spiral keeps the tour identical across reloads.
const TOUR = [0.61, 0.13, 0.88, 0.34, 0.72, 0.05, 0.49, 0.95, 0.27, 0.66];

export default function SmoothZooming({ width }: { width: number }) {
  const ref = useRef<SVGSVGElement>(null);
  const height = Math.round(width * 0.55);

  // Sized so the spiral overfills the frame at every width, as in the notebook.
  const radius = useMemo(
    () => Math.max(0.5, (0.75 * Math.max(width, height)) / Math.sqrt(POINTS) / 2),
    [width, height]
  );

  const points = useMemo(() => {
    const step = radius * 2;
    return Array.from({ length: POINTS }, (_, i) => {
      const index = i + 0.5;
      const distance = step * Math.sqrt(index);
      const angle = THETA * index;
      return [
        width / 2 + distance * Math.cos(angle),
        height / 2 + distance * Math.sin(angle)
      ] as [number, number];
    });
  }, [radius, width, height]);

  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    const svg = d3.select(element);
    svg.selectAll('*').remove(); // StrictMode runs this effect twice

    const group = svg.append('g');

    group
      .selectAll('circle')
      .data(points)
      .join('circle')
      .attr('cx', (d) => d[0])
      .attr('cy', (d) => d[1])
      .attr('r', radius)
      .attr('fill', (_, i) => d3.interpolateRainbow(i / 360));

    const transform = ([x, y, r]: View) =>
      `translate(${width / 2},${height / 2}) scale(${height / r}) translate(${-x},${-y})`;

    let view: View = [width / 2, height / 2, height];
    group.attr('transform', transform(view));

    let step = 0;
    function tourNext() {
      const target = points[Math.floor(TOUR[step % TOUR.length] * POINTS)];
      step += 1;
      const interpolate = d3.interpolateZoom(view, [target[0], target[1], radius * 2 + 1]);

      group
        .transition()
        .delay(DELAY)
        .duration(interpolate.duration)
        .attrTween('transform', () => (t) => transform((view = interpolate(t))))
        // An interrupted transition fires 'interrupt', not 'end', so cleanup ends the chain.
        .on('end', tourNext);
    }
    tourNext();

    return () => {
      group.interrupt();
      svg.selectAll('*').interrupt();
      svg.selectAll('*').remove();
    };
  }, [points, radius, width, height]);

  if (width === 0) return null;

  return (
    <svg
      ref={ref}
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Phyllotaxis spiral of coloured dots touring itself with smooth pan-and-zoom transitions"
      style={{ display: 'block' }}
    />
  );
}
